package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.fuel.*;
import io.github.astelev.around_planet.propulsion.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.fluids.*;
import net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction;
@net.neoforged.neoforge.gametest.PrefixGameTestTemplate(false)
public final class CryogenicGameTests {
 @GameTest(template="empty",templateNamespace="around_planet",timeoutTicks=100)
 public static void ownFluidsAndPreciseStorageWorkWithoutPetrochem(GameTestHelper h){var level=h.getLevel();var p=h.absolutePos(new BlockPos(1,2,1));level.setBlockAndUpdate(p,PropulsionRegistry.LIQUID.get().defaultBlockState());try{var be=(PropulsionBlockEntity)level.getBlockEntity(p);h.assertTrue(be.controlValue()==1&&be.maximumThrust()==20,"New engine flow defaults/cap incorrect");be.configure(1000);h.assertTrue(be.controlValue()==20,"Settings bypassed flow cap");var legacy=be.saveWithoutMetadata(level.registryAccess());legacy.putDouble("Thrust",1000);be.loadWithComponents(legacy,level.registryAccess());h.assertTrue(be.controlValue()==20,"Legacy flow was not clamped");var cap=level.getCapability(net.neoforged.neoforge.capabilities.Capabilities.FluidHandler.BLOCK,p,null);h.assertTrue(cap!=null&&cap.getTanks()==2,"Own engine fluid capability missing");var bucket=FluidUtil.getFluidContained(new net.minecraft.world.item.ItemStack(CryogenicFluids.HYDROGEN_BUCKET.get())).orElseThrow();h.assertTrue(bucket.getFluid().isSame(CryogenicFluids.HYDROGEN.get())&&bucket.getAmount()==1000,"Own bucket does not contain own hydrogen");h.assertTrue(cap.fill(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000),FluidAction.EXECUTE)==0,"Engine accepted water as rocket fuel");h.assertTrue(cap.fill(bucket,FluidAction.SIMULATE)==1000&&be.rocket.fuel()==0,"Simulation consumed fuel");cap.fill(bucket,FluidAction.EXECUTE);cap.fill(new FluidStack(CryogenicFluids.OXYGEN.get(),1000),FluidAction.EXECUTE);var burn=be.rocket.burn(.001,FuelMassBridge.kgPerMb(be,false),FuelMassBridge.kgPerMb(be,true));h.assertTrue(burn.mass()>0&&be.rocket.fuel()<1000&&be.rocket.fuel()>999,"Sub-millibucket combustion was rounded away");var tag=be.saveWithoutMetadata(level.registryAccess());double stored=be.rocket.fuel();be.rocket.restore(0,0);be.loadWithComponents(tag,level.registryAccess());h.assertTrue(be.rocket.fuel()==stored,"Fractional storage did not survive NBT");h.assertTrue(cap.getFluidInTank(0).getAmount()==999,"Fluid extraction rounded the fractional remainder upward");h.succeed();}finally{level.removeBlock(p,false);}}
}
